/* Plain CSS */
.button {
  color: blue;
}
.link {
  color: blue;
}

/* SASS */
$primary-color: blue;

.button {
  color: $primary-color;
}
.link {
  color: $primary-color;
}

// Defining a mixin
@mixin flex-center {
  display: flex;
  justify-content: center;
  align-items: center;
}

// Using the mixin
.container {
  @include flex-center;
}

// Mixin with parameters
@mixin button-style($bg-color) {
  background-color: $bg-color;
  padding: 10px 20px;
  border-radius: 5px;
}

.primary-btn {
  @include button-style(blue);
}

// Nested SASS
nav {
  background-color: #333;

  ul {
    list-style: none;

    li {
      display: inline-block;

      a {
        color: white;
        text-decoration: none;

        &:hover {
          color: yellow;
        }
      }
    }
  }
}

// SASS syntax (indentation based, no braces/semicolons)
.button
  color: white
  background-color: blue
  padding: 10px

// SCSS syntax (uses braces and semicolons, like CSS)
.button {
  color: white;
  background-color: blue;
  padding: 10px;
}
